import sys
from math import gcd
from collections import defaultdict

sys.setrecursionlimit(300000)

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    n = int(next(iterator))

    a = [0] * (n + 1)
    max_val = 0
    for i in range(1, n + 1):
        val = int(next(iterator))
        a[i] = val
        max_val = max(max_val, val)

    adj = [[] for _ in range(n + 1)]
    for _ in range(n - 1):
        u = int(next(iterator))
        v = int(next(iterator))
        adj[u].append(v)
        adj[v].append(u)

    ans = defaultdict(int)

    def dfs(u, p, current_gcds):
        new_gcds = {}
        g = a[u]
        if g in current_gcds:
            new_gcds[g] = current_gcds[g] + 1
        else:
            new_gcds[g] = 1

        for v in adj[u]:
            if v == p:
                continue

            child_gcds = dfs(v, u, current_gcds)

            for g_child, count_child in child_gcds.items():
                g_new = gcd(g, g_child)
                if g_new in new_gcds:
                    new_gcds[g_new] += count_child
                else:
                    new_gcds[g_new] = count_child

        for g_val, count in new_gcds.items():
            ans[g_val] += count

        return new_gcds

    dfs(1, 0, {})

    output_lines = []
    for i in range(1, 200001):
        if ans[i] > 0:
            output_lines.append(f"{i} {ans[i]}")

    sys.stdout.write('\n'.join(output_lines) + '\n')

if __name__ == '__main__':
    main()
